MarketComparisonPage::~MarketComparisonPage(){feed->cancel();regionFeed->cancel();}
void MarketComparisonPage::hideEvent(QHideEvent*event){refreshTimer->stop();feed->cancel();regionFeed->cancel();QWidget::hideEvent(event);}
void MarketComparisonPage::showEvent(QShowEvent*event){QWidget::showEvent(event);readCache();scheduleRefresh();}
QJsonArray MarketComparisonPage::selected()const{QJsonArray out;for(int n=0;n<choices->count();++n)if(choices->item(n)->checkState()==Qt::Checked)out.append(choices->item(n)->data(Qt::UserRole).toJsonObject());return out;}
QString MarketComparisonPage::mode()const{return tabs->currentIndex()==1?QString("leading"):tabs->currentIndex()==2?QString("pace"):period->currentData().toString();}
void MarketComparisonPage::loadCatalog(){QJsonArray items=marketComparison::indexDefinitions();QString warning;try{regionEvidence=regionFeed->read();for(auto v:regionEvidence["catalog"].toObject()["items"].toArray())items.append(v);}catch(const std::exception&e){warning=QString("地区缓存拒绝：")+e.what();}if(!catalogFile.isEmpty()){QFile f(catalogFile);try{if(f.exists()){if(f.size()>8*1024*1024||!f.open(QIODevice::ReadOnly))throw std::runtime_error("板块目录不可读或超限");auto imported=boardSeries::legacyCatalog(f.readAll());for(auto v:imported["items"].toArray())items.append(v);for(auto v:imported["unsupported"].toArray()){auto row=v.toObject();if(row["provider"].toString().startsWith("sina-public-"))items.append(marketComparison::composite::definition(row));}if(!imported["unsupported"].toArray().isEmpty()&&feed->compositeDatasetIdentity().isEmpty())warning="当前成分等权估算缺少本机前复权基线；自身指数与估算不按同名合并。";}}catch(const std::exception&e){warning=QString("目录拒绝：")+e.what();}}for(auto v:catalog)if(v.toObject()["kind"]=="stock")items.append(v);auto old=selected();catalog=items;rebuildChoices();restoring=true;for(auto v:old){QJsonValue key=v.toObject()["key"];bool found=false;for(int n=0;n<choices->count();++n)if(choices->item(n)->data(Qt::UserRole).toJsonObject()["key"]==key){choices->item(n)->setCheckState(Qt::Checked);found=true;break;}if(!found){auto d=v.toObject();auto*item=new QListWidgetItem(displayName(d)+" · 原选择",choices);item->setData(Qt::UserRole,d);item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(Qt::Checked);}}restoring=false;filterChoices();if(!warning.isEmpty())status->setText(warning);}
void MarketComparisonPage::setCatalogItems(const QJsonArray&items){auto keep=selected();const auto before=catalog.size();QSet<QString>keys;for(auto v:catalog)keys.insert(v.toObject()["key"].toString());for(auto v:items)try{auto d=marketComparison::definition(v.toObject());if(!keys.contains(d["key"].toString())){keys.insert(d["key"].toString());catalog.append(d);}}catch(const std::exception&e){status->setText(QString("目录条目拒绝：")+e.what());}if(catalog.size()!=before){rebuildChoices();restoring=true;for(auto v:keep){auto d=v.toObject();QListWidgetItem*found=nullptr;for(int n=0;n<choices->count();++n)if(choices->item(n)->data(Qt::UserRole).toJsonObject()["key"]==d["key"]){found=choices->item(n);break;}if(!found){found=new QListWidgetItem(displayName(d)+" · 原明确身份",choices);found->setData(Qt::UserRole,d);found->setFlags(found->flags()|Qt::ItemIsUserCheckable);}if(found->data(Qt::UserRole).toJsonObject()!=d){found->setData(Qt::UserRole,d);found->setText(displayName(d)+" · 原明确身份");found->setToolTip(displayName(d)+" · "+d["key"].toString());}found->setCheckState(Qt::Checked);}restoring=false;}filterChoices();readCache();scheduleRefresh();}
void MarketComparisonPage::rebuildChoices(){QSignalBlocker guard(choices);choices->clear();QSet<QString>keys;for(auto v:catalog)try{auto d=marketComparison::definition(v.toObject());if(keys.contains(d["key"].toString()))continue;keys.insert(d["key"].toString());auto*item=new QListWidgetItem(displayName(d),choices);item->setToolTip(displayName(d)+" · "+d["key"].toString());item->setData(Qt::UserRole,d);item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(Qt::Unchecked);item->setIcon(marketComparison::seriesIcon(d["key"].toString()));}catch(const std::exception&){} filterChoices();}
void MarketComparisonPage::filterChoices(){
 const auto term=search->text().trimmed();int matches=0;
 for(int n=0;n<choices->count();++n){auto* item=choices->item(n);const auto row=item->data(Qt::UserRole).toJsonObject();
  const bool match=item->text().contains(term,Qt::CaseInsensitive)||row["code"].toString().contains(term,Qt::CaseInsensitive);
  item->setHidden(!match);matches+=match;
 }
 search->setToolTip(QString("匹配 %1 项；过滤不会取消已选标的").arg(matches));
}
void MarketComparisonPage::loadSecurities(){
 const auto root=QFileInfo(directory).absolutePath();
 securitiesReader=new PageSnapshotReader(this,[root]{
  auto rows=SecuritiesLegacyStore(root+"/securities-legacy-v1.sqlite").directory();
  const auto publicRows=securitiesCatalog::Cache(root+"/securities-public-v1").read("directory")["result"].toObject()["items"].toArray();for(auto row:publicRows)rows.append(row);
  QJsonArray definitions;for(auto value:rows){const auto row=value.toObject();const auto market=row["market"].toString(),code=row["code"].toString();
   if(row["canOpen"]!=true||row["type"]!="stock"||(market!="SH"&&market!="SZ"))continue;
   definitions.append(QJsonObject{{"key","stock:"+market+":"+code},{"kind","stock"},{"name",row["name"]},{"code",code},{"symbol",market.toLower()+code},{"providerId",market.toLower()+code}});
  }return QJsonObject{{"definitions",definitions}};
 },[this](QJsonObject result,QString error){if(error.isEmpty())setCatalogItems(result["definitions"].toArray());else status->setText("证券搜索目录未载入："+error);});
 securitiesReader->request();
}
void MarketComparisonPage::clearFrames(){if(cacheReader)cacheReader->cancel();plot->setFrame({});leadingPlot->setFrame({});pacePlot->setFrame({});matrix->setRowCount(0);matrix->setColumnCount(0);shown={};}
void MarketComparisonPage::selectionChanged(){refreshTimer->stop();feed->cancel();clearFrames();readCache();remember();scheduleRefresh();}
void MarketComparisonPage::readCache(){auto m=mode();auto defs=requestDefinitions();count->setText(QString(allow?"已选 %1 个 · 切换选项更新图表":"已选 %1 个 · 离线浏览").arg(selected().size()));if(defs.size()<2&&m!="leading"){status->setText("请选择至少2个明确对象。");clearFrames();return;}try{if(!cacheReader)cacheReader=new PageSnapshotReader(this,{},[this](QJsonObject report,QString error){setProperty("snapshotLoading",false);if(error.isEmpty())render(report);else status->setText(error);});setProperty("snapshotLoading",true);cacheReader->request(feed->readTask(m,defs,window->currentData().toInt()));}catch(const std::exception&e){status->setText(e.what());}}
void MarketComparisonPage::refreshCurrent(){if(feed->busy())return;refreshTimer->stop();if(!isVisible()||!allow)return;auto m=mode();auto defs=requestDefinitions();if(defs.size()<2&&m!="leading"){status->setText("请选择至少2个明确对象。");return;}try{if(cacheReader)cacheReader->cancel();setProperty("snapshotLoading",false);feed->start(m,defs,window->currentData().toInt());}catch(const std::exception&e){status->setText(e.what());}}
void MarketComparisonPage::render(QJsonObject value){QElapsedTimer elapsed;elapsed.start();shown=value;setProperty("cacheAndCalculationMs",value["cacheAndCalculationMs"].toDouble());auto m=value["mode"].toString();if(m.isEmpty())return;auto rows=value[m=="pace"?"sourceSeries":"series"].toArray();int usable=0;bool cached=false,stale=false,partial=false;QString html="<h3>来源、读取与缺口</h3><p>公开源；读取时间不等于交易所报价时刻。未知值保留空缺。板块自身历史复用P04；地区BK复用相同自身指数接口。新浪估算只用当前完整成分，存在幸存者偏差，不是历史真实成分或供应商指数。</p>";for(auto v:rows){auto r=v.toObject();usable+=r["status"]=="available";cached|=r["cache"].toBool();stale|=r["stale"].toBool()||r["lastAttempt"].toObject()["status"]=="failed";partial|=r["partial"].toBool()||r["lastAttempt"].toObject()["status"]=="partial";html+="<h4>"+displayName(r).toHtmlEscaped()+" · "+text(r["key"])+"</h4><p>状态："+text(r["status"])+"；来源："+text(r["source"])+"<br>来源URL："+text(r["sourceUrl"])+"<br>原读取："+text(r["fetchedAt"])+"；源时刻：未提供<br>可用点："+QString::number(r["points"].toArray().size())+"；部分数据："+(r["partial"].toBool()?"是":"否")+"<br>原因："+text(r["reason"])+"<br>最近尝试："+text(r["lastAttempt"])+"<br>降级记录："+QString::fromUtf8(QJsonDocument(r["fallbackErrors"].toArray()).toJson(QJsonDocument::Compact)).toHtmlEscaped()+"</p>";}for(auto v:rows){auto r=v.toObject();if(r["historyMode"]==marketComparison::composite::historyMode)html+="<h4>当前成分等权估算边界</h4><p>当前成分总数 "+QString::number(r["requestedConstituents"].toInt())+"；本地纳入 "+QString::number(r["includedConstituents"].toInt())+"；每日门槛 "+QString::number(r["minimumDailyCoverage"].toInt())+"（分母为本地纳入数）<br>基线："+text(r["dataset"])+"<br>当前名单："+text(r["constituentEvidence"])+"<br>警告："+QString::fromUtf8(QJsonDocument(r["warnings"].toArray()).toJson(QJsonDocument::Compact)).toHtmlEscaped()+"</p>";}html+="<p>基线限制：仅消费已有原生前复权数据包，旧Parquet须先转换；本页不启动Python、不回填历史成分。"+compositeLoadError.toHtmlEscaped()+"</p>";html+="<p>地区目录回执："+text(regionEvidence)+"</p>";html+="<p>请求回执："+QString::fromUtf8(QJsonDocument(value["attempts"].toArray()).toJson(QJsonDocument::Compact)).toHtmlEscaped()+"</p>";html+="<p>本次读取："+text(value["servedAt"])+"</p>";sources->setHtml(html);status->setText(QString("%1 · 可用%2/%3%4%5%6 · %7").arg(value["status"]=="available"?"可用":value["status"]=="partial"?"部分可用":"不可用").arg(usable).arg(rows.size()).arg(cached?" · 历史观测":"").arg(stale?" · 刷新失败保留旧值":"").arg(partial?" · 来源窗口/字段不完整":"").arg(value["tradingDate"].toString()));if(m=="pace"){auto paceFrame=marketComparison::paceFrame(value);paceFrame["viewScope"]=requestKey();paceFrame["tradingDate"]=value["tradingDate"];pacePlot->setFrame(paceFrame,true);auto metrics=value["metrics"].toObject();bool complete=value["quality"].toObject()["usable"].toBool();auto measure=value["measure"].toString()=="volume"?"5分钟成交量（不是成交额）":"1分钟成交额";paceStatus->setText(QString("%1；%2 对 %3，截止 %4\n累计同比 %5%；5分钟同比 %6%；5分钟环比 %7%\n%8；覆盖%9/%10。阈值沿用旧未校准规则；沪深指数代理口径未独立验证。").arg(measure,value["tradingDate"].toString(),value["comparisonDate"].toString(),value["asOf"].toString(),complete?num(metrics["cumulativeYoYPct"]):QString("不可用"),num(metrics["rolling5YoYPct"]),num(metrics["rolling5SequentialPct"]),value["reason"].toString(),QString::number(value["coverage"].toObject()["alignedPoints"].toInt()),QString::number(value["coverage"].toObject()["expectedAlignedPoints"].toInt())));return;}if(m=="leading"){auto r=rows.isEmpty()?QJsonObject():rows[0].toObject();bool actual=r["leadingIndicator"].toObject()["available"].toBool();auto leadingFrame=marketComparison::leadingFrame(r);leadingFrame["viewScope"]=requestKey();leadingFrame["tradingDate"]=r["tradingDate"];leadingPlot->setFrame(leadingFrame,true);leadingStatus->setText(actual?"已取得真实不加权领先字段；白/黄线保留原值，未用均价或均线替代。":r["status"]=="available"?"真实领先字段不可用；仅绘制已知加权白线。":"没有可验证分时点；白线、领先黄线均不可用。" );return;}auto frame=value["comparison"].toObject();auto lineRows=frameSeries(frame["series"].toArray(),basis->currentIndex()==1);QJsonArray labeled;for(auto v:lineRows){auto line=v.toObject();for(auto r:rows)if(r.toObject()["key"]==line["key"])line["name"]=displayName(r.toObject());line["color"]=marketComparison::seriesColor(line["key"].toString()).name();labeled.append(line);}frame["series"]=labeled;frame["title"]=basis->currentText()+(m=="intraday"?" · "+QString(frame["basis"]=="previous-close-100"?"前收统一基准":"共同首点统一基准"):" · 所有可用对象共同日期");frame["viewScope"]=requestKey();plot->setFrame(frame,true);auto corr=value["correlation"].toObject();auto keys=corr["keys"].toArray();QStringList names;for(auto key:keys){QString name=key.toString();for(auto r:rows)if(r.toObject()["key"]==key)name=displayName(r.toObject());names<<name;}QSignalBlocker matrixSignals(matrix);matrix->setUpdatesEnabled(false);matrix->setRowCount(keys.size());matrix->setColumnCount(keys.size());matrix->setHorizontalHeaderLabels(names);matrix->setVerticalHeaderLabels(names);for(int n=0;n<keys.size();++n){auto icon=marketComparison::seriesIcon(keys[n].toString());matrix->horizontalHeaderItem(n)->setIcon(icon);matrix->verticalHeaderItem(n)->setIcon(icon);}auto values=corr["values"].toArray(),samples=corr["sampleCounts"].toArray();for(int r=0;r<keys.size();++r)for(int c=0;c<keys.size();++c){auto numbers=values[r].toArray(),counts=samples[r].toArray();auto*cell=new QTableWidgetItem((numbers[c].isDouble()?QString::number(numbers[c].toDouble(),'f',3):"—"));cell->setToolTip(QString("有效对数收益样本%1；至少%2，零方差也不可用").arg(counts[c].toInt()).arg(corr["minSamples"].toInt()));cell->setTextAlignment(Qt::AlignCenter);matrix->setItem(r,c,cell);}matrix->setUpdatesEnabled(true);setProperty("matrixAndUiMs",double(elapsed.nsecsElapsed())/1000000.); }
QJsonObject MarketComparisonPage::saveState()const{return {{"schema","native-market-comparison-ui/v1"},{"compositeDatasetSha",compositeSelectionExplicit?QJsonValue(desiredCompositeSha):feed->compositeDatasetIdentity()["sha256"]},{"definitions",selected()},{"period",period->currentData().toString()},{"window",window->currentData().toInt()},{"basis",basis->currentIndex()},{"tab",tabs->currentIndex()},{"leading",leadingIndex->currentIndex()},{"viewport",plot->saveViewport()},{"leadingViewport",leadingPlot->saveViewport()},{"paceViewport",pacePlot->saveViewport()}};}
void MarketComparisonPage::restoreState(const QJsonObject&state){if(state["schema"]!="native-market-comparison-ui/v1")return;refreshTimer->stop();feed->cancel();restoring=true;QSignalBlocker guard(choices);for(int n=0;n<choices->count();++n)choices->item(n)->setCheckState(Qt::Unchecked);QSet<QString>seen;for(auto v:state["definitions"].toArray())try{auto d=marketComparison::definition(v.toObject());if(seen.contains(d["key"].toString()))continue;seen.insert(d["key"].toString());QListWidgetItem*found=nullptr;for(int n=0;n<choices->count();++n)if(choices->item(n)->data(Qt::UserRole).toJsonObject()["key"]==d["key"])found=choices->item(n);if(!found){found=new QListWidgetItem(displayName(d)+" · 原明确身份",choices);found->setData(Qt::UserRole,d);found->setFlags(found->flags()|Qt::ItemIsUserCheckable);}found->setCheckState(Qt::Checked);}catch(const std::exception&){}int p=period->findData(state["period"].toString());if(p>=0)period->setCurrentIndex(p);int w=window->findData(state["window"].toInt());if(w>=0)window->setCurrentIndex(w);basis->setCurrentIndex(std::clamp(state["basis"].toInt(),0,1));tabs->setCurrentIndex(std::clamp(state["tab"].toInt(),0,3));leadingIndex->setCurrentIndex(std::clamp(state["leading"].toInt(),0,7));window->setEnabled(period->currentData()=="daily");if(state.contains("compositeDatasetSha")){compositeSelectionExplicit=true;desiredCompositeSha=state["compositeDatasetSha"].toString();int index=compositeDatasetPicker->findData(state["compositeDatasetSha"].toString());compositeDatasetPicker->setCurrentIndex(std::max(0,index));applyCompositeDataset();}restoring=false;filterChoices();readCache();plot->restoreViewport(state["viewport"].toObject());leadingPlot->restoreViewport(state["leadingViewport"].toObject());pacePlot->restoreViewport(state["paceViewport"].toObject());scheduleRefresh();}
void MarketComparisonPage::remember(){if(restoring)return;QDir().mkpath(directory);QSaveFile f(directory+"/selection-v1.json");if(!f.open(QIODevice::WriteOnly)){status->setText("选择未能保存；已有缓存保留。");return;}auto bytes=QJsonDocument(saveState()).toJson(QJsonDocument::Compact);if(f.write(bytes)!=bytes.size()||!f.commit())status->setText("选择保存失败；已有缓存保留。");}

void MarketComparisonPage::setCompositeDatasets(const QJsonArray&input){
 if(input.size()>100)throw std::runtime_error("本地前复权基线超过100项，未隐式截断");
 auto before=compositeSelectionExplicit?desiredCompositeSha:feed->compositeDatasetIdentity()["sha256"].toString();QJsonArray accepted;QSet<QString>seen;for(auto v:input){auto data=v.toObject();auto meta=marketComparison::composite::identity(data);auto key=meta["sha256"].toString();if(!seen.contains(key)){accepted.append(data);seen.insert(key);}}
 QList<QJsonObject> sorted;for(auto v:accepted)sorted.append(v.toObject());std::stable_sort(sorted.begin(),sorted.end(),[](auto a,auto b){return a["asOf"].toString()>b["asOf"].toString();});compositeDatasets={};bool priorRestoring=restoring;restoring=true;compositeDatasetPicker->clear();compositeDatasetPicker->addItem("未选前复权基线（估算不可用）",QString());for(auto data:sorted){compositeDatasets.append(data);auto meta=marketComparison::composite::identity(data);compositeDatasetPicker->addItem(data["datasetId"].toString()+" · "+data["asOf"].toString(),meta["sha256"].toString());}int index=compositeDatasetPicker->findData(before);compositeDatasetPicker->setCurrentIndex(index>=1?index:!compositeSelectionExplicit&&before.isEmpty()&&!sorted.isEmpty()?1:0);restoring=priorRestoring;applyCompositeDataset();if(!restoring){readCache();remember();scheduleRefresh();}
}
void MarketComparisonPage::applyCompositeDataset(){int index=compositeDatasetPicker->currentIndex()-1;feed->setCompositeDataset(index>=0&&index<compositeDatasets.size()?compositeDatasets[index].toObject():QJsonObject{});}
void MarketComparisonPage::loadCompositeWorkspace(){if(!compositeReader)compositeReader=new PageSnapshotReader(this,[path=QFileInfo(directory).absolutePath()+"/quant-research-v1.json"]{QFile f(path);QJsonArray data;if(f.exists()){if(!f.open(QIODevice::ReadOnly)||f.size()>32*1024*1024)throw std::runtime_error("已有量化库不可读或超过32MiB");data=marketComparison::composite::datasets(f.readAll());}return QJsonObject{{"data",data}};},[this](QJsonObject result,QString error){if(!error.isEmpty()){compositeLoadError=error;status->setText("基线未重载："+error);return;}try{setCompositeDatasets(result["data"].toArray());compositeLoadError.clear();}catch(const std::exception&e){status->setText(e.what());}});compositeReader->request();}

QJsonArray MarketComparisonPage::requestDefinitions()const{if(mode()=="leading")return {leadingIndex->currentData().toJsonObject()};if(mode()=="pace"){auto fixed=marketComparison::indexDefinitions();return {fixed[0],fixed[1]};}return selected();}
QString MarketComparisonPage::requestKey()const{return QString::fromUtf8(QJsonDocument(QJsonObject{{"mode",mode()},{"definitions",requestDefinitions()},{"window",window->currentData().toInt()},{"dataset",feed->compositeDatasetIdentity()}}).toJson(QJsonDocument::Compact));}
void MarketComparisonPage::scheduleRefresh(){refreshTimer->stop();if(allow&&isVisible()&&!restoring&&tabs->currentIndex()<3)refreshTimer->start(180);}
void MarketComparisonPage::refreshAutomatically(){
 if(!allow||!isVisible()||restoring||tabs->currentIndex()>=3)return;if(feed->busy()||QWidget::window()->isMinimized()){refreshTimer->start(marketRefresh::chinaInterval(QDateTime::currentDateTimeUtc(),refreshFailures));return;}auto defs=requestDefinitions();if(defs.size()<(mode()=="leading"?1:2))return;
 auto now=QDateTime::currentMSecsSinceEpoch();auto key=requestKey();if(attempted.contains(key)&&now-attempted.value(key)>=0&&now-attempted.value(key)<60000){refreshTimer->start(int(60000-(now-attempted.value(key))));return;}
 auto rows=shown[mode()=="pace"?"sourceSeries":"series"].toArray();bool fresh=shown["mode"]==mode()&&rows.size()==defs.size();
 for(auto v:rows){auto r=v.toObject();auto at=QDateTime::fromString(r["fetchedAt"].toString(),Qt::ISODateWithMs);auto age=at.msecsTo(QDateTime::currentDateTimeUtc());fresh&=r["status"]=="available"&&!r["partial"].toBool()&&r["lastAttempt"].toObject()["status"]!="failed"&&at.isValid()&&age>=0&&age<60000;}
 if(!fresh)refreshCurrent();else refreshTimer->start(marketRefresh::chinaInterval(QDateTime::currentDateTimeUtc(),refreshFailures));
}
